int read_quant_matrix(MpegEncContext *s, GetBitContext *gb) {
    int i;

    if (s->workaround_bugs & FF_BUG_QP)
        s->intra_quant_matrix[0] = get_bits(gb, 8);
    else
        s->intra_quant_matrix[0] = 16;

    if (get_bits_left(gb) < 64 * 8)
        return AVERROR_INVALIDDATA;

    for (i = 1; i < 64; i++) {
        s->intra_quant_matrix[i] = get_bits(gb, 8);
    }

    return 0;
}

int read_quant_matrix(MpegEncContext *s, GetBitContext *gb) {
    int i;
    int *quant_matrix = s->intra_quant_matrix;

    if (s->mpeg2 && s->width == 704 && s->height == 576 && s->avctx->codec_id == AV_CODEC_ID_MPEG2VIDEO) {
        s->q_scale_type = 1;
    }

    if (get_bits_left(gb) < 64 * 8) {
        return AVERROR_INVALIDDATA;
    }

    for (i = 0; i < 64; i++) {
        quant_matrix[ff_zigzag_direct[i]] = get_bits(gb, 8);
    }

    return 0;
}

int read_quantization_matrix(MpegEncContext *s, GetBitContext *gb) {
    int i;

    // Check if a specific bug workaround is needed and set edge positions
    if (s->avctx->workaround_bugs & FF_BUG_QP)
        s->q_intra = get_bits(gb, 8);
    else
        s->q_intra = get_bits(gb, 5);

    // Check if there are enough bits left in the stream to read the matrix
    if (get_bits_left(gb) < 64 * 8)
        return AVERROR_INVALIDDATA;

    // Read 64 values into the intra quantizer matrix using zigzag pattern
    for (i = 0; i < 64; i++) {
        s->intra_matrix[zigzag_direct[i]] = get_bits(gb, 8);
    }

    return 0;
}

int read_quant_matrix(MpegEncContext *s, GetBitContext *gb) {
    int i;
    int bug_edge = 0;

    // Check if a bug workaround is needed and set edge positions
    if (s->avctx->debug & FF_DEBUG_BUGS) {
        bug_edge = 1;
    }

    // Check if there are enough bits left to read the quantization matrix
    if (bitstream_remaining(gb) < 64 * 8) {
        return AVERROR_INVALIDDATA;
    }

    // Read 64 values into the intra quantizer matrix using zigzag pattern
    for (i = 0; i < 64; i++) {
        s->intra_quant_matrix[zigzag_scan[i]] = get_bits8(gb);
    }

    return 0;
}
